package wal
import("bytes";"fmt";"testing")
func TestTornTailRecoversPrefix(t *testing.T){var records []Record;var buf []byte;var ends []int;for i:=0;i<20;i++{r:=Record{Op:OpPut,Key:[]byte(fmt.Sprintf("k%02d",i)),Value:bytes.Repeat([]byte{byte(i)},i)};records=append(records,r);buf=append(buf,Encode(r)...);ends=append(ends,len(buf))};for cut:=0;cut<=len(buf);cut++{var got []Record;valid:=Decode(buf[:cut],func(r Record){got=append(got,r)});want:=0;for _,end:=range ends{if end<=cut{want++}};if len(got)!=want{t.Fatalf("cut %d got %d want %d",cut,len(got),want)};for i:=range got{if !bytes.Equal(got[i].Key,records[i].Key)||!bytes.Equal(got[i].Value,records[i].Value){t.Fatalf("record %d mismatch",i)}};if want>0&&valid!=ends[want-1]{t.Fatalf("valid prefix %d want %d",valid,ends[want-1])}}}
func TestCorruptRecordStopsReplay(t *testing.T){var buf []byte;for i:=0;i<10;i++{buf=append(buf,Encode(Record{Op:OpPut,Key:[]byte(fmt.Sprintf("k%d",i)),Value:[]byte("v")})...)};buf[40]^=0xff;n:=0;Decode(buf,func(Record){n++});if n>=10{t.Fatal("corrupt record was not detected")}}
